cd /app/work && python3 -c "
import json,sys
sys.path.insert(0,'/app/work'); sys.path.insert(0,'/app/submission')
import ref as R, main as M
text = open('fail_sup.json').read()
root = json.loads(text, object_pairs_hook=M._hook_pairs, parse_float=M._reject_float, parse_constant=M._reject_constant)
st = M.validate(root)
mine = M.replay(st); theirs = R.replay(st)
for k in mine:
    if mine[k]!=theirs[k]:
        print('differs:', k)
        if k=='packets':
            for i,(a,b) in enumerate(zip(mine[k],theirs[k])):
                if a!=b: print(' pkt',i); print('  mine',a); print('  ref ',b)
        elif k=='jobs':
            for i,(a,b) in enumerate(zip(mine[k],theirs[k])):
                if a!=b: print(' job',i); print('  mine',a); print('  ref ',b)
        else:
            print(' mine',json.dumps(mine[k])[:400]); print(' ref ',json.dumps(theirs[k])[:400])
print(json.dumps(json.loads(text)['config'], indent=1))
"
